<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,api,loadWorkspaces,loadData} from '../state'
const router=useRouter(),busy=ref(false),message=ref(''),error=ref(''),cooldown=ref(0)
let timer:any,ticks=0
async function check(){try{state.user=await api('/auth/me');if(state.user.verified){await loadWorkspaces();await loadData();const invite=sessionStorage.getItem('sd_invite');router.replace(invite?'/invite?token='+invite:state.workspace?.onboarded?'/overview':'/onboarding')}}catch{}}
async function resend(){busy.value=true;error.value='';try{const r=await api('/auth/resend-verification',{method:'POST'});message.value=r.delivery_enabled?t('A new confirmation link is on its way. Check spam and promotions too.','Новая ссылка отправляется. Проверьте также спам и промоакции.'):t('Email delivery is disabled in this environment.','Отправка писем отключена в этой среде.');cooldown.value=60}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function change(){await api('/auth/logout',{method:'POST'});state.user=null;state.workspace=null;state.workspaces=[];router.push('/register')}
onMounted(()=>{if(!state.user){router.replace('/login');return}check();timer=setInterval(()=>{if(cooldown.value)cooldown.value--;if(++ticks%5===0)check()},1000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="verification-page"><section class="card verification-card"><span class="auth-icon"><Icon name="Mail" :size="28"/></span><span class="eyebrow">{{t('ONE QUICK SECURITY CHECK','ПОДТВЕРДИТЕ ВАШУ ПОЧТУ')}}</span><h1>{{t('Check your inbox.','Проверьте почту.')}}</h1><p>{{t('We sent a confirmation link to','Мы отправили ссылку для подтверждения на')}} <strong>{{state.user?.email}}</strong>.</p><p class="muted">{{t('Confirm your email to unlock company onboarding and your workspace. This page will continue automatically after confirmation.','Подтвердите почту, чтобы перейти к настройке компании и открыть рабочее пространство. Эта страница продолжит работу автоматически.')}}</p><div v-if="message" class="notice success-notice" role="status">{{message}}</div><div v-if="error" class="notice error-notice" role="alert">{{error}}</div><button class="btn primary full large-btn" @click="check"><Icon name="MailCheck" :size="18"/>{{t('I’ve confirmed my email','Я подтвердил почту')}}</button><button class="btn secondary full mt-sm" @click="resend" :disabled="busy||cooldown>0">{{t('Resend confirmation link','Отправить ссылку ещё раз')}}{{cooldown?' · '+cooldown+'s':''}}</button><button class="text-link center mt-sm" @click="change">{{t('Use a different email','Использовать другую почту')}}</button><p class="small muted mt-lg"><Icon name="ShieldCheck" :size="15"/> {{t('Your workspace stays locked until you verify ownership of this address.','Рабочее пространство закрыто до подтверждения, что эта почта принадлежит вам.')}}</p></section></div></template>
